public sealed partial class WorldSession
{
    public HouseFreightView? HouseFreightView(){lock(gate)return HouseLogistics.View(state);}
    public CommandResult ManageHouseFreight(HouseFreightInput input,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||!HouseLogistics.Enabled(state)||input.Carrier is {} carrier&&carrier==state.PlayerControl)return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,"本人の運搬ではありません");var old=state.HouseFreight!.Entries.SingleOrDefault(e=>e.Input.Id==input.Id);if(old!=null)return new(old.Input==input?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"操作済みです");if(FactionStances.OtherIdUsed(state,input.Id)||FactionStances.OwnIdUsed(state,input.Id))return new(ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"別原本で使用済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,input.Id,state.CommitSequence,"条件を読み直してください");EntityId? assigned=null;if(input.Job is {} job&&state.HouseFreight!.Entries.SingleOrDefault(e=>e.Terms?.Id==job)?.Terms is {} terms&&terms.Carrier!=actor){if(input.Action!=HouseFreightAction.Withdraw||!NpcFreight.CanRecallAtMeeting(state,job))return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,"家臣の荷を遠隔操作できません");assigned=terms.Carrier;}try{Change(w=>{if(assigned is {} person)HouseLogistics.ApplyFor(w,input,person);else HouseLogistics.Apply(w,input);});return new(ResultCode.Accepted,input.Id,state.CommitSequence,"家の預り金・荷・受渡しを記録しました");}catch(Exception e)when(e is InvalidDataException or ArgumentException or InvalidOperationException or OverflowException){return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,e.Message);}}}
}
